(function(root){const images=['book','pen','cup','bag','shirt','box'];const api={images,errors(p,publish,qualified){const e=[];if(!p.name?.trim())e.push('请填写商品名称');if(publish){if(!p.description?.trim())e.push('请填写商品介绍');if(!['ordinary','licensed'].includes(p.category))e.push('请选择准入类目');if(!images.includes(p.image))e.push('请选择一张预置商品图片');if(p.category==='licensed'&&!qualified)e.push('该类目需要已通过且有效的专项资质');if(!p.variants.length)e.push('请添加至少一个规格');if(!Number.isInteger(p.defaultVariant)||!p.variants[p.defaultVariant])e.push('请选择默认规格');}p.variants.forEach((v,i)=>{const title='规格 '+(i+1)+'：';if(publish&&!v.name.trim())e.push(title+'请填写名称');if(v.price!==''||publish){if(!/^\d+(\.\d{1,2})?$/.test(v.price)||Number(v.price)<=0||!Number.isSafeInteger(Math.round(Number(v.price)*100)))e.push(title+'价格须大于 0，最多两位小数');}if(v.stock!==''||publish){if(!/^\d+$/.test(v.stock)||!Number.isSafeInteger(Number(v.stock)))e.push(title+'库存须为非负整数');}});return e;}};if(typeof module!=='undefined')module.exports=api;else root.ProductEditorModel=api;})(globalThis);
